export interface ProviderMarkStop {
  offset: number;
  color: string;
}

// x1…y2 are fractions of the part's bounding box (SVG's objectBoundingBox units), copied from the owner's SVG.
export interface ProviderMarkGradient {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  stops: readonly ProviderMarkStop[];
}

export type ProviderMarkPart = { d: string; color: string; gradient?: undefined } | { d: string; gradient: ProviderMarkGradient; color?: undefined };

export type ProviderMark = { d: string; color: string; parts?: undefined } | { parts: readonly ProviderMarkPart[]; d?: undefined; color?: undefined };

